var hosts = [
    "https://www.suduguu.com",
    "https://shudugu.org",
    "https://sudugu520.com"
];

function getHosts() {
    return hosts;
}

function getServerHost() {
    var source = this.source;
    try {
        var config = JSON.parse(source.getVariable());
        if (config && config[0] && config[0].host) {
            return config[0].host;
        }
        return getHosts()[0];
    } catch (e) {
        return getHosts()[0];
    }
}

function getConfig() {
    var source = this.source;
    try {
        var configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getHosts()[0] };
        }
        var config = JSON.parse(configStr);
        if (!config || !config.join || config.length === 0) {
            return { host: getHosts()[0] };
        }
        return config[0] || { host: getHosts()[0] };
    } catch (e) {
        return { host: getHosts()[0] };
    }
}

function setConfig(key, value) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        config[key] = value;
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function setConfigs(obj) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        for (var k in obj) {
            if (obj.hasOwnProperty(k)) {
                config[k] = obj[k];
            }
        }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function checkConnectivity(host) {
    var timeout = 5000;
    var socket = null;
    try {
        var start = new Date().getTime();
        var jUrl = new Packages.java.net.URL(host);
        var hostname = jUrl.getHost();
        var port = jUrl.getPort();
        if (port === -1) { port = jUrl.getDefaultPort(); }
        socket = new Packages.java.net.Socket();
        var addr = new Packages.java.net.InetSocketAddress(hostname, port);
        socket.connect(addr, timeout);
        var latency = new Date().getTime() - start;
        return {ok: true, latency: latency};
    } catch (e) {
        return {ok: false, latency: -1, err: String(e)};
    } finally {
        try { if (socket !== null) { socket.close(); } } catch (e2) {}
    }
}

function autoSelectHost() {
    var allHosts = getHosts();
    var details = [];
    var best = null;
    var bestLatency = -1;
    for (var i = 0; i < allHosts.length; i++) {
        var r = checkConnectivity.call(this, allHosts[i]);
        r.host = allHosts[i];
        details.push(r);
        if (r.ok && (bestLatency < 0 || r.latency < bestLatency)) {
            best = allHosts[i];
            bestLatency = r.latency;
        }
    }
    if (best !== null) {
        setConfig.call(this, 'host', best);
    }
    return {success: best !== null, host: best, details: details};
}

