var base = String(baseUrl);
var hostM = base.match(/^https?:\/\/[^\/]+/);
var host = hostM ? hostM[0] : '';
var h = String(result);
var bidM = h.match(/BookID\s*=\s*"(\d+)"/);
var aidM = h.match(/ArticleID\s*=\s*"(\d+)"/);
var bid = bidM ? bidM[1] : '';
var aid = aidM ? aidM[1] : '';
function extractP(text) {
    var out = '';
    var pm = text.match(/<p>[\s\S]*?<\/p>/g);
    if (!pm || pm.length === 0) {
        var dm = text.match(/document\.write\((['"])([\s\S]*?)\1\)/);
        if (dm) {
            pm = dm[2].match(/<p>[\s\S]*?<\/p>/g);
        }
    }
    if (!pm) return '';
    for (var i = 0; i < pm.length; i++) {
        var t = pm[i].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
        if (t) out += t + '\n';
    }
    return out;
}
var allContent = '';
try {
    var ps = org.jsoup.Jsoup.parse(h).select('.con p');
    for (var i = 0; i < ps.size(); i++) {
        var t = ps.get(i).text().trim();
        if (t) allContent += t + '\n';
    }
} catch (e1) { }
if (bid && aid) {
    for (var p = 2; p <= 15; p++) {
        try {
            var url = host + '/i/a.aspx?id=' + aid + '&p=' + p + '&bid=' + bid;
            var opts = {
                headers: {
                    'Referer': base,
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
                }
            };
            var resp = String(java.ajax(url + ',' + JSON.stringify(opts), 15000));
            var got = extractP(resp);
            if (!got) break;
            allContent += got;
        } catch(e2) {
            break;
        }
    }
}
allContent.replace(/\n+$/, '\n');

