this.sethost = function() {
    try {
        var currentHost = getConfig.call(this).host || getHosts()[0];
        var currentIndex = getHosts().indexOf(currentHost);
        var newIndex = (currentIndex + 1) % getHosts().length;
        var newHost = getHosts()[newIndex];
        setConfig.call(this, 'host', newHost);
        java.toast("\n已切换到：\n" + newHost + "\n刷新发现页生效");
    } catch(e) {
        setConfig.call(this, 'host', getHosts()[0]);
        java.toast("\n已初始化：" + getHosts()[0]);
    }
};

this.checkhost = function() {
    try {
        var currentHost = getServerHost();
        java.toast("\n当前服务器：\n" + currentHost);
    } catch(e) {
        java.toast("获取失败");
    }
};

this.autohost = function() {
    try {
        java.toast("\n正在检测，请稍候...");
        var result = autoSelectHost.call(this);
        var msg = "";
        for (var i = 0; i < result.details.length; i++) {
            var d = result.details[i];
            var shortName = d.host.replace("https://","").replace("http://","");
            if (d.ok) {
                msg += "\n✓ " + shortName + "  " + d.latency + "ms";
            } else {
                msg += "\n✗ " + shortName + "  不可达";
            }
        }
        if (result.success) {
            msg += "\n\n已选中：" + result.host.replace("https://","");
        } else {
            msg += "\n\n全部不可达";
        }
        java.toast(msg);
    } catch(e) {
        java.toast("检测异常：" + String(e));
    }
};

this.pinghost = function() {
    try {
        var currentHost = getServerHost();
        var r = checkConnectivity.call(this, currentHost);
        var shortName = currentHost.replace("https://","").replace("http://","");
        if (r.ok) {
            java.toast("\n当前域名：\n" + shortName + "\n延迟：" + r.latency + "ms");
        } else {
            java.toast("\n当前域名：\n" + shortName + "\n连接失败");
        }
    } catch(e) {
        java.toast("检测异常：" + String(e));
    }
};

this.smartswitch = function() {
    try {
        var current = getServerHost();
        var shortCurrent = current.replace("https://","").replace("http://","");
        var r = checkConnectivity.call(this, current);
        if (r.ok) {
            java.toast("\n✓ 当前域名正常\n" + shortCurrent + "\n延迟：" + r.latency + "ms\n无需切换");
            return;
        }
        java.toast("\n✗ 当前域名不可达\n" + shortCurrent + "\n正在自动选可用...");
        var result = autoSelectHost.call(this);
        if (result.success) {
            var msg = "\n已自动切换到：\n" + result.host.replace("https://","").replace("http://","");
            for (var i = 0; i < result.details.length; i++) {
                var d = result.details[i];
                if (d.ok) {
                    msg += "\n  " + d.host.replace("https://","").replace("http://","") + "  " + d.latency + "ms";
                }
            }
            msg += "\n\n请返回书架重进章节";
            java.toast(msg);
        } else {
            java.toast("\n全部域名不可达\n请检查网络或稍后重试");
        }
    } catch(e) {
        java.toast("智能换源异常：" + String(e));
    }
};

