var aidM = h.match(/ArticleID\s*=\s*"(\d+)"/);
var bid = bidM ? bidM[1] : '';
var aid = aidM ? aidM[1] : '';
function extractP(text) {
    var out = '';
    var pm = text.match(/<p>[\s\S]*?<\/p>/g);
    if (!pm || pm.length === 0) {
        var dm = text.match(/document\.write\((['"])([\s\S]*?)\1\)/);
        if (dm) {
            pm = dm[2].match(/<p>[\s\S]*?<\/p>/g);
        }
    }
    if (!pm) return '';
    for (var i = 0; i < pm.length; i++) {
        var t = pm[i].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
        if (t) out += t + '\n';
    }
    return out;
}
var allContent = '';
try {
    var ps = org.jsoup.Jsoup.parse(h).select('.con p');
    for (var i = 0; i < ps.size(); i++) {
        var t = ps.get(i).text().trim();
        if (t) allContent += t + '\n';
    }
} catch (e1) { }
if (bid && aid) {
    for (var p = 2; p <= 15; p++) {
        try {
            var url = host + '/i/a.aspx?id=' + aid + '&p=' + p + '&bid=' + bid;
            var opts = {
                headers: {
